import {tickets,today} from './data.js';
import {pending,overdue,record,decide,review} from './domain.js';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let view='tickets',filter='all';
const fmt=s=>new Date(s).toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'});
function render(){const list=tickets.filter(t=>t.condo===$('#condo').value),late=list.filter(t=>overdue(t,today)),rec=list.filter(t=>list.some(o=>o.id!==t.id&&o.local===t.local&&o.category===t.category));
$('#metrics').innerHTML=[['Em acompanhamento',list.filter(t=>t.status!=='Concluído').length,'all'],['Retornos vencidos',late.length,'late'],['Decisões pendentes',list.filter(pending).length,'decisions'],['Possíveis reincidências',rec.length,'repeat']].map(([label,n,key])=>`<button data-filter="${key}"><strong>${n}</strong><span>${label}</span></button>`).join('');
$('h1').textContent=view==='decisions'?'Decidir com clareza.':view==='new'?'Toda demanda tem um caminho.':'Uma rotina mais leve.';
if(view==='new'){ $('#content').innerHTML=`<div class="panel"><h2>Simular entrada pelo WhatsApp</h2><p>Mensagem do morador via WhatsApp • condomínio identificado: ${esc($('#condo').value)}</p><form id="new-form"><label>Resumo<input name="title" required maxlength="120"></label><label>Local<input name="local" required maxlength="100"></label><label>Categoria<select name="category"><option>Manutenção</option><option>Iluminação</option><option>Limpeza</option><option>Convivência</option></select></label><label>Descrição<textarea name="description" required maxlength="1500"></textarea></label><button class="primary">Gerar protocolo</button></form></div>`;$('#new-form').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));if(!data.title.trim()||!data.local.trim()||!data.description.trim())return;const t={...data,id:Math.max(...tickets.map(t=>t.id))+1,condo:$('#condo').value,status:'Em triagem',owner:'Ana • TRÍADE',response:'2026-10-04T12:00',resolution:'2026-10-08T18:00',history:['Demanda recebida automaticamente. Prazos iniciais fictícios, sujeitos à triagem.'],evidence:'',closure:''};tickets.push(t);view='tickets';filter='all';render();open(t.id);};return;}
let shown=view==='decisions'?list.filter(pending):filter==='late'?late:filter==='repeat'?rec:list;
$('#content').innerHTML=`<div class="section-title"><div><h2>${view==='decisions'?'Autorizações necessárias':'Fila de acompanhamento'}</h2><p>Referência do cenário: 03/10/2026, 15h • ${esc($('#condo').value)}</p></div><button id="reset">Ver todos</button></div><div class="cards">${shown.map(t=>`<button class="ticket" data-id="${t.id}"><div><small>TRI-${t.id} • ${esc(t.category)}</small><span class="badge">${esc(t.status)}</span></div><h3>${esc(t.title)}</h3><p>${esc(t.local)}</p><div class="dates"><span class="${overdue(t,today)?'late':''}">Próximo retorno<br><b>${fmt(t.response)}</b></span><span>Previsão de resolução<br><b>${fmt(t.resolution)}</b></span></div><p class="owner">${esc(t.owner)} <span>Ver acompanhamento →</span></p></button>`).join('')||'<div class="panel">Nenhuma demanda nesta fila.</div>'}</div>`;
$('#reset').onclick=()=>{view='tickets';filter='all';render();};document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>open(Number(b.dataset.id)));
}
function open(id){const t=tickets.find(t=>t.id===id),isOp=$('#role').value==='Operação';const d=$('#detail');d.innerHTML=`<button class="close" aria-label="Fechar">×</button><small>TRI-${t.id} • ${esc(t.condo)}</small><h2>${esc(t.title)}</h2><span class="badge">${esc(t.status)}</span><p>${esc(t.description)}</p><p><b>Responsável:</b> ${esc(t.owner)}<br><b>Retorno:</b> ${fmt(t.response)}<br><b>Resolução estimada:</b> ${fmt(t.resolution)}</p>${t.decision?`<section class="decision"><h3>${esc(t.decision.text)}</h3><p>${esc(t.decision.options)}</p><b>${esc(t.decision.state)}</b>${pending(t)&&!isOp?'<label>Justificativa<textarea id="reason" maxlength="1000"></textarea></label><button class="primary" id="approve">Autorizar (simulação)</button> <button id="reject">Devolver à triagem</button>':''}<p class="hint">A resposta não contrata serviço nem movimenta dinheiro.</p></section>`:''}<h3>Histórico de acompanhamento</h3><ol class="timeline">${t.history.map(h=>`<li>${esc(h)}</li>`).join('')}</ol>${isOp&&t.status!=='Concluído'?`<section class="panel"><h3>Atualizar acompanhamento</h3><form id="update"><label>Mensagem ao morador<textarea name="message" required maxlength="1000"></textarea></label><label>Próximo retorno<input name="response" type="datetime-local" value="${esc(t.response)}" required></label><label>Pendência / estado<select name="status">${['Em triagem','Em andamento','Aguardando fornecedor','Aguardando equipe','Aguardando morador',...(pending(t)?['Aguardando síndico']:[])].map(s=>`<option ${s===t.status?'selected':''}>${s}</option>`).join('')}</select></label><button>Registrar retorno simulado</button></form></section>${!pending(t)?'<section class="panel"><h3>Preparar encerramento</h3><label>Evidência (referência fictícia)<input id="evidence" maxlength="500" placeholder="Ex.: foto do teste e checklist da vistoria"></label><label>Explicação da solução<textarea id="closure" maxlength="1000"></textarea></label><button id="prepare">Enviar à revisão</button>'+(t.status==='Em revisão'?'<button class="primary" id="review">Revisar e concluir</button>':'')+'</section>':''}`:''}${t.status==='Concluído'?`<p><b>Solução:</b> ${esc(t.closure)}<br><b>Evidência:</b> ${esc(t.evidence)}</p>${isOp?'<label>Motivo da reabertura<textarea id="reopen-reason"></textarea></label><button id="reopen">Reabrir chamado</button>':''}`:''}<p id="error" role="alert"></p>`;
d.querySelector('.close').onclick=()=>d.close();if(!d.open)d.showModal();const action=(selector,fn)=>{const el=d.querySelector(selector);if(el)el.onclick=()=>{try{fn();render();open(id);}catch(e){$('#error').textContent=e.message;}};};action('#approve',()=>decide(t,'Aprovado',$('#reason').value));action('#reject',()=>decide(t,'Devolvido',$('#reason').value));
const form=$('#update');if(form)form.onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(form));if(!v.message.trim())return; t.response=v.response;t.status=v.status;record(t,`Retorno ao morador simulado: ${v.message}. Estado: ${v.status}`);render();open(id);};
if($('#evidence')){$('#evidence').value=t.evidence;$('#closure').value=t.closure;}
action('#prepare',()=>{if(!$('#evidence').value.trim()||!$('#closure').value.trim())throw Error('Preencha evidência e explicação.');t.evidence=$('#evidence').value;t.closure=$('#closure').value;t.status='Em revisão';record(t,'Execução registrada; aguardando revisão da operação.');});action('#review',()=>review(t));action('#reopen',()=>{if(!$('#reopen-reason').value.trim())throw Error('Informe o motivo da reabertura.');t.status='Em andamento';record(t,`Reaberto: ${$('#reopen-reason').value}`);});}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;filter='all';render();});$('#condo').onchange=()=>{filter='all';render();};$('#role').onchange=()=>{view=$('#role').value==='Síndico'?'decisions':'tickets';filter='all';render();};$('#metrics').onclick=e=>{const b=e.target.closest('[data-filter]');if(!b)return;filter=b.dataset.filter;view=filter==='decisions'?'decisions':'tickets';render();};$('#detail').addEventListener('click',e=>{if(e.target===$('#detail'))$('#detail').close();});render();
